(require '[clojure.string :as str] '[clojure.edn :as edn])
(def project (System/getenv "KOTOBASE_ORACLE_ROOT"))
(def writer (System/getenv "GIB_LINKED_WRITER"))
(load-string (first (str/split (slurp writer) #"\(def dir \(str base" 2)))
(def dir (str base "/store")) (def stage (str base "/stage"))
(def backend (fb/open-backend dir stage tool))
(defn open-db [b] (core/open {:storage b :encrypt-fn identity :decrypt-fn identity :blind-fn pr-str :visible? (constantly true)}))
(def ids (edn/read-string (slurp (str base "/ids.edn"))))
(assert (= (:commit ids) (:cid (storage/-read-ref backend "linked-gib"))))
(def records (:receipt/records (causal/receipt-at (open-db backend) (:commit ids) (:cid ids))))
(assert (= 3 (count records))) (assert (= authority-receipt (second records)))
(defn checked-value [cid] (let [b (storage/get-block backend cid)] (assert b) (let [v (codec/decode-value b)] (assert (= cid (codec/value-cid v))) v)))
(def receipt (first records)) (def r (checked-value (:request/digest receipt))) (def m (checked-value (:execution/manifest receipt))) (def loc (checked-value (:location/manifest m)))
(ec/validate-manifest-request! m r) (assert (= request* r)) (assert (= file-manifest m)) (assert (= file-location loc))
(assert (true? ((:verify opts) {:record :execution-manifest :tenant (:tenant r) :epoch (:authority/epoch r) :payload-cid (id/payload-cid m) :signature (:signature m)})))
(assert (true? ((:verify opts) {:record :execution-receipt :tenant (:tenant r) :epoch (:authority/epoch r) :payload-cid (id/payload-cid receipt) :signature (:signature receipt)})))
(let [changed-location (assoc loc :logical-file signed-basis)
      changed-manifest (assoc m :location/manifest (codec/value-cid changed-location))]
  (assert (not (true? ((:verify opts) {:record :execution-manifest :tenant (:tenant r) :epoch (:authority/epoch r) :payload-cid (id/payload-cid changed-manifest) :signature (:signature m)})))))
(assert (true? (link/verify! {:link (nth records 2) :request r :query query :execution-receipt receipt :authority-receipt (second records) :value-cid id/value-cid :verify (:verify opts)})))
(assert (try (link/verify! {:link (nth records 2) :request (assoc r :nonce "wrong") :query query :execution-receipt receipt :authority-receipt (second records) :value-cid id/value-cid :verify (:verify opts)}) false (catch Exception _ true)))
(let [v (first (car/cbor-decode (mapv #(bit-and 255 %) ((:get-block file-view) file-cid)) 0)) md (MessageDigest/getInstance "SHA-256")]
 (doseq [[i c] (map-indexed vector (get v "chunks"))] (let [bytes ((:get-block file-view) (car/cid-str (get-in c ["cid" :bytes])))] (assert (= (get c "length") (alength ^bytes bytes))) (.update md ^bytes bytes)) (when (zero? (mod (inc i) 256)) (prn {:readback (inc i)}) (flush)))
 (assert (= expected-sha (.formatHex (HexFormat/of) (.digest md)))))
(assert (= file-root-before (:root (store/read-store (str file-base "/store")))))
(prn {:fresh-process :verified :signed-location :verified :altered-location :rejected :wrong-request :rejected :records 3 :file-blocks 1024 :file-sha expected-sha :pass true})
(shutdown-agents)
